//! The oracle is generated by ffmpeg lavfi and the unmodified Python analyse function.
use dt_media::{PcmAudio, analyse};
use serde_json::Value;

#[test]
fn matches_python_analysis() {
    let fixture: Value = serde_json::from_str(include_str!("analysis_golden.json")).unwrap();
    // Reconstruct the lavfi expression, rounding to signed 16-bit just as ffmpeg does.
    // Keeping this arithmetic here makes the committed oracle test independent of tools/Python.
    let frames = fixture["pcm_frames"].as_u64().unwrap() as usize;
    let samples: Vec<[i16; 2]> = (0..frames)
        .map(|i| {
            let t = i as f64 / 48000.0;
            let tau = std::f64::consts::TAU;
            let left = 0.16 * (tau * (40.0 * t + 875.0 * t * t)).sin()
                + 0.65 * (tau * 58.0 * t).sin() * (-35.0 * (t % 0.5)).exp();
            let right = 0.12 * (tau * (90.0 * t + 650.0 * t * t)).sin()
                + 0.55 * (tau * 71.0 * t).sin() * (-40.0 * ((t + 0.09) % 0.75)).exp();
            [
                (left * 32768.0).round() as i16,
                (right * 32768.0).round() as i16,
            ]
        })
        .collect();
    let hash = samples
        .iter()
        .flatten()
        .flat_map(|s| s.to_le_bytes())
        .fold(0xcbf29ce484222325_u64, |h, byte| {
            (h ^ u64::from(byte)).wrapping_mul(0x100000001b3)
        });
    assert_eq!(
        format!("{hash:016x}"),
        fixture["pcm_fnv1a64"].as_str().unwrap(),
        "synthetic PCM differs from ffmpeg oracle"
    );
    let features = analyse(&PcmAudio { samples }).unwrap();
    let tolerance = fixture["envelope_absolute_tolerance"].as_f64().unwrap();
    assert_eq!(features.len(), fixture["bass"].as_array().unwrap().len());
    let mut max_error = 0.0_f64;
    for i in 0..features.len() {
        let frame = features.get(i).unwrap();
        for (b, &value) in frame.bands.iter().enumerate() {
            let expected = fixture["bands"][i][b].as_f64().unwrap();
            let error = (f64::from(value) - expected).abs();
            max_error = max_error.max(error);
            assert!(
                error <= tolerance,
                "band {b}, frame {i}: {value} vs {expected}"
            );
        }
        for (name, value) in [("bass", frame.bass), ("kick", frame.kick)] {
            let expected = fixture[name][i].as_f64().unwrap();
            let error = (f64::from(value) - expected).abs();
            max_error = max_error.max(error);
            assert!(
                error <= tolerance,
                "{name}, frame {i}: {value} vs {expected}"
            );
        }
        assert_eq!(
            f64::from(frame.ring),
            fixture["ring"][i].as_f64().unwrap(),
            "ring frame {i}"
        );
    }
    println!("maximum absolute envelope error: {max_error:.9}");
}
